  ('e312ee19-783b-42eb-a8d7-f26d4a518255', 'cf77a7a3-d651-47d6-84e4-da2725a0bc72', $$inleiding: creditzijde van de balans van Duijff Diervoeders nv per 1 januari 2019$$,
