  ('fe5b8f86-f63c-4f63-9b34-32ba386ec44b', '6dd7cd6d-38fd-4a84-aa57-020bc3e9806c', $$inleiding: btw buiten beschouwing; Schrijf & Zo bv groothandel in kantoormiddelen$$,
