  ('7490cbf6-75c6-48c1-85a3-08f550517df0', '6dd7cd6d-38fd-4a84-aa57-020bc3e9806c', $$tabel kengetallen Schrijf & Zo en kantoormiddelenbranche per 31 december 2020$$,
