  ('fcda10df-44cb-4acc-819d-13fac268be2c', 'da8646c0-34fc-4ea6-8222-b1107cd1435a', $$Uitwerkbijlage vraag 24$$,
   $$bedrijfseconomie-vwo-2021-ii-paul-van-haperen-uitwerkbijlage24.png$$,
