   $$bedrijfseconomie-vwo-2021-ii-duijff-diervoeders-nv-vraag2.png$$, $$3p 2 Bereken het bedrag dat als gevolg van de verdeling van het resultaat over 2019 aan de Dividendreserve wordt toegevoegd.$$, array['e312ee19-783b-42eb-a8d7-f26d4a518255', '71e4356c-4838-490e-97fa-e8b68157d602', '49917f90-6804-4868-9083-e7c544a02f4e', '4b030ac6-fa0f-4236-a130-bc5c087e14f9', 'bcd0a75c-b226-405b-93fc-fa1f9463646e', 'e7adb2ca-8917-4908-97b1-0170bcc3f7c8', '3889324c-c1b4-47bd-8c07-4be95f96831c']::uuid[]),
